    std::string severity;
    switch (status_text.type) {
        case Telemetry::StatusTextType::Emergency: severity = "Emergency"; break;
        case Telemetry::StatusTextType::Alert: severity = "Alert"; break;
        case Telemetry::StatusTextType::Critical: severity = "Critical"; break;
        case Telemetry::StatusTextType::Error: severity = "Error"; break;
        case Telemetry::StatusTextType::Warning: severity = "Warning"; break;
        case Telemetry::StatusTextType::Notice: severity = "Notice"; break;
        case Telemetry::StatusTextType::Info: severity = "Info"; break;
        case Telemetry::StatusTextType::Debug: severity = "Debug"; break;
        default: severity = "Unknown"; break;
    }
    std::cout << "Status: [" << severity << "] " << status_text.text << '\n';
});

    // Keep the program running to continue receiving status text
    while (true) {
        sleep_for(seconds(1));
    }

    return 0;
}
